/* ==UserStyle==
@name           Roblox Navbar Title Customizer
@namespace      stylish-roblox-navbar-customizer
@version        1.9
@description    Changes "Charts" to "Games" and "Robux" to "ROBUX" in the Roblox navigation bar.
@author         Faxel
@preprocessor   stylus
==/UserStyle== */

/* Change "Charts" to "Games" */
a[href*="/charts"]:not([class*="hidden"]) {
    visibility: hidden;
}

a[href*="/charts"]:not([class*="hidden"]):before {
    content: "Games" !important;
    visibility: visible;
    display: flex;
    align-items: center; /* Vertically center the text */
    justify-content: center; /* Horizontally center the text */
    width: 100%;
}

/* Change "Robux" to "ROBUX" */
a[href*="/robux"]:not([class*="hidden"]) {
    visibility: hidden;
}

a[href*="/robux"]:not([class*="hidden"]):before {
    content: "ROBUX" !important;
    visibility: visible;
    display: flex;
    align-items: center; /* Vertically center the text */
    justify-content: center; /* Horizontally center the text */
    width: 100%;
}

a[href*="/avatar"]:not([class*="hidden"]):after {
    content: "Character" !important;
    visibility: visible;
    display: flex;
    align-items: left; /* Vertically center the text */
    justify-content: left; /* Horizontally center the text */
    width: 180%;
}

a[href*="/communities"]:not([class*="hidden"]):after {
    content: "Groups" !important;
    visibility: visible;
    display: flex;
    align-items: left; /* Vertically center the text */
    justify-content: left; /* Horizontally center the text */
    width: 180%;
}
